const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [
  {
    json: {
      ...$json,
      sinceIsoDate: sevenDaysAgo.toISOString(),
      todayIsoDate: now.toISOString(),
      formattedDateRange: `${sevenDaysAgo.toISOString().slice(0, 10)} to ${now.toISOString().slice(0, 10)}`
    }
  }
];

const config = $('Configuration Variables').item.json;
const dateRange = $('Calculate Date Range (7 Days)').item.json.formattedDateRange;
const sinceDate = new Date($('Calculate Date Range (7 Days)').item.json.sinceIsoDate);

// 1. Process Commits
const rawCommits = $('Fetch Weekly Commits').all() || [];
const commitSummaries = rawCommits.map(item => {
  const c = item.json;
  const author = c.commit?.author?.name || c.author?.login || 'contributor';
  const message = (c.commit?.message || '').split('\n')[0];
  return `- [${c.sha ? c.sha.slice(0, 7) : 'commit'}] ${message} (@${author})`;
}).slice(0, 20);

// 2. Process Closed Issues (filter out PRs)
const rawIssues = $('Fetch Closed Issues').all() || [];
const closedIssues = rawIssues
  .filter(item => !item.json.pull_request)
  .map(item => {
    const iss = item.json;
    return `- #${iss.number}: ${iss.title} (${(iss.labels || []).map(l => l.name).join(', ') || 'unlabeled'})`;
  }).slice(0, 15);

// 3. Process Merged PRs
const rawPulls = $('Fetch Closed PRs').all() || [];
const mergedPulls = rawPulls
  .filter(item => item.json.merged_at && new Date(item.json.merged_at) >= sinceDate)
  .map(item => {
    const pr = item.json;
    return `- PR #${pr.number}: ${pr.title} by @${pr.user?.login || 'unknown'}`;
  }).slice(0, 15);

const language = (config.SUMMARY_LANGUAGE || 'EN').toUpperCase() === 'FR' ? 'French (Français)' : 'English';

const prompt = `You are an expert technical writer and developer advocate for the open-source repository ${config.GITHUB_REPO_OWNER}/${config.GITHUB_REPO_NAME}.

Your task is to write an engaging, insightful, and comprehensive weekly developer narrative summary for the period ${dateRange}.

Language requirement: Write the entire summary in ${language}.

Here is the raw activity data from GitHub:

### Merged Pull Requests (${mergedPulls.length}):
${mergedPulls.join('\n') || 'None this week'}

### Closed Issues (${closedIssues.length}):
${closedIssues.join('\n') || 'None this week'}

### Recent Commits (${commitSummaries.length}):
${commitSummaries.join('\n') || 'None this week'}

### Structure of Your Summary:
1. 🚀 **Key Highlights & Big Wins** (Top accomplishments and features shipped)
2. 🛠️ **Engineering & Bug Fixes** (Key stability improvements and fixes)
3. 🤝 **Community & Contributors** (Shoutouts to active contributors)
4. 🔮 **What to Watch Next Week** (Looking ahead)

Keep the tone professional, upbeat, clear, and well-formatted with GitHub Flavored Markdown and emoji. Avoid fluff.`;

return [{
  json: {
    prompt,
    repoOwner: config.GITHUB_REPO_OWNER,
    repoName: config.GITHUB_REPO_NAME,
    language,
    dateRange,
    stats: {
      commitsCount: commitSummaries.length,
      closedIssuesCount: closedIssues.length,
      mergedPRsCount: mergedPulls.length
    }
  }
}];

